        import math

def _min_sum_hv(a, b, u):
    # Solve a*h + b*v = u for nonnegative integers h, v minimizing h+v.
    d = math.gcd(a, b)
    if u % d != 0:
        return None
    a1, b1, u1 = a // d, b // d, u // d
    # modular inverse of a1 mod b1
    def inv_mod(x, m):
        if m == 1:
            return 0
        # extended Euclid
        def eg(a, b):
            if b == 0:
                return (1, 0, a)
            x, y, g = eg(b, a % b)
            return (y, x - (a // b) * y, g)
        s, t, g = eg(x % m, m)
        if g != 1:
            return None
        return s % m
    inv_a = inv_mod(a1, b1)
    if inv_a is None:
        return None
    h0 = (u1 * inv_a) % b1
    v0 = (u1 - a1 * h0) // b1
    # general solution: h = h0 + t*b1, v = v0 - t*a1
    # bounds for t to keep h,v >= 0
    t_low = math.ceil((-h0) / b1) if b1 != 0 else 0
    t_high = math.floor(v0 / a1) if a1 != 0 else 0
    if t_low > t_high:
        return None
    # minimize L(t) = h+v = h0+v0 + t*(b1 - a1)
    if b1 > a1:
        t_opt = t_high
    elif b1 < a1:
        t_opt = t_low
    else:
        t_opt = t_low
    h = h0 + t_opt * b1
    v = v0 - t_opt * a1
    if h < 0 or v < 0:
        return None
    return (h, v)


